import * as MP4 from './metadata/index.mjs'

import { overwriteDefault } from './utils/objects.mjs'
import { isBuffer } from './utils/types.mjs'

export default class MP4Tag {
  get name () { return 'MP4Tag' }
  set name (value) { throw new Error('Unable to set this property') }

  get version () { return '0.1.0-beta' }
  set version (value) { throw new Error('Unable to set this property') }

  constructor (buffer, verbose = false) {
    if (!isBuffer(buffer)) {
      throw new TypeError('buffer is not ArrayBuffer/Buffer')
    }

    this.verbose = verbose
    this.buffer = buffer
    this.metadata = {}
    this.boxes = []
    this.error = ''
  }

  static decodeMetadata (buffer, options = {}, verbose = false) {
    if (!isBuffer(buffer)) {
      throw new TypeError('buffer is not ArrayBuffer/Buffer')
    }

    if (verbose) console.log('Reading MP4 boxes...')
    const decoded = MP4.decodeMetadata(buffer)
    if (verbose) console.log('Finished reading MP4...')

    return decoded
  }

  read (options = {}) {
    this.metadata = {}
    this.boxes = []
    this.error = ''

    try {
      const decoded = MP4Tag.decodeMetadata(this.buffer, options, this.verbose)
      this.metadata = decoded.metadata
      this.boxes = decoded.boxes
    } catch (error) {
      this.error = error.message
    }

    return this.metadata
  }

  static encodeMetadata (metadata, boxes, options = {}, verbose = false) {
    options = overwriteDefault(options, { strict: false })

    if (verbose) console.log('Validating metadata...')
    MP4.validate(metadata, boxes, options.strict)

    if (verbose) console.log('Writing metadata...')
    const encoded = MP4.encodeMetadata(metadata, boxes, options)
    return typeof Buffer !== 'undefined' ? Buffer.from(encoded) : encoded.buffer
  }

  save (options = {}) {
    this.error = ''
    try {
      this.buffer = MP4Tag.encodeMetadata(this.metadata, this.boxes, options, this.verbose)
    } catch (error) {
      this.error = error.message
    }

    return this.buffer
  }
}
